"""Parsers for catalog.txt, movements.txt and orders.txt, and stock levels."""

from __future__ import annotations

import datetime
import re
from decimal import Decimal
from typing import Dict, Iterator, List, Optional, Tuple

from .model import Movement, Order, ParseError, Product

_WS = " \t"
_SKU_RE = re.compile(r"[A-Za-z]{2,4}-[0-9]{3}")
_ORDER_RE = re.compile(r"[Ss][Oo]-[0-9]+")
_DATE_RE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}")
_PRICE_RE = re.compile(r"[0-9]+(\.[0-9]{1,2})?")
_UINT_RE = re.compile(r"[0-9]+")
_SIGNED_RE = re.compile(r"[+-]?[0-9]+")
_MOVE_RE = re.compile(r"([^ \t]+)[ \t]+([^ \t]+)[ \t]+([^ \t]+)(?:[ \t]+(.*))?", re.DOTALL)
_TAXES = ("standard", "reduced", "zero")


def normalise_sku(text: str) -> Optional[str]:
    """Upper-case SKU, or None when ``text`` is not shaped like a SKU."""
    if _SKU_RE.fullmatch(text):
        return text.upper()
    return None


def normalise_order_id(text: str) -> Optional[str]:
    """Upper-case order id, or None when ``text`` is not shaped like one."""
    if _ORDER_RE.fullmatch(text):
        return text.upper()
    return None


def parse_date(text: str) -> Optional[datetime.date]:
    """A real ``YYYY-MM-DD`` date, or None."""
    if not _DATE_RE.fullmatch(text):
        return None
    try:
        return datetime.date(int(text[:4]), int(text[5:7]), int(text[8:]))
    except ValueError:
        return None


def parse_uint(text: str) -> Optional[int]:
    """A whole number of ASCII digits, or None."""
    if not _UINT_RE.fullmatch(text):
        return None
    try:
        return int(text)
    except ValueError:  # absurdly long
        return None


def iter_lines(text: str) -> Iterator[Tuple[int, str]]:
    """Yield ``(line number, trimmed line)`` for lines that carry data.

    Lines end at LF (one CR before it is dropped); a leading BOM is ignored;
    blank lines and ``#`` comments are skipped but still counted.
    """
    if text.startswith("﻿"):
        text = text[1:]
    for number, raw in enumerate(text.split("\n"), 1):
        if raw.endswith("\r"):
            raw = raw[:-1]
        line = raw.strip(_WS)
        if not line or line.startswith("#"):
            continue
        yield number, line


def parse_catalog(text: str) -> Dict[str, Product]:
    catalog: Dict[str, Product] = {}
    for number, line in iter_lines(text):
        fields = [f.strip(_WS) for f in line.split("|")]
        if len(fields) not in (4, 5):
            raise ParseError(number, "expected 4 or 5 fields separated by '|', found %d" % len(fields))
        raw_sku, name, raw_price, raw_reorder = fields[:4]
        sku = normalise_sku(raw_sku)
        if sku is None:
            raise ParseError(number, "invalid SKU %r" % raw_sku)
        if sku in catalog:
            raise ParseError(number, "duplicate SKU %s" % sku)
        if not name:
            raise ParseError(number, "name is empty")
        if not _PRICE_RE.fullmatch(raw_price):
            raise ParseError(number, "invalid price %r" % raw_price)
        price = Decimal(raw_price)
        if price < Decimal("0.01"):
            raise ParseError(number, "price must be at least 0.01")
        reorder = parse_uint(raw_reorder)
        if reorder is None:
            raise ParseError(number, "invalid reorder level %r" % raw_reorder)
        tax = "standard"
        if len(fields) == 5:
            tax = fields[4].lower() if fields[4].isascii() else fields[4]
            if tax not in _TAXES:
                raise ParseError(number, "invalid tax %r (standard, reduced or zero)" % fields[4])
        catalog[sku] = Product(sku, name, price, reorder, tax)
    return catalog


def check_balances(entries: List[Tuple[int, Movement]]) -> None:
    """Raise ParseError on the line that first takes a SKU below zero.

    ``entries`` are ``(line, movement)`` in file order; movements count in
    date order, file order within a day.
    """
    balance: Dict[str, int] = {}
    for line, move in sorted(entries, key=lambda e: e[1].date):
        total = balance.get(move.sku, 0) + move.quantity
        if total < 0:
            raise ParseError(line, "stock of %s would go below zero" % move.sku)
        balance[move.sku] = total


def parse_movements(text: str, catalog: Dict[str, Product]) -> List[Movement]:
    entries: List[Tuple[int, Movement]] = []
    for number, line in iter_lines(text):
        match = _MOVE_RE.fullmatch(line)
        if match is None:
            raise ParseError(number, "expected DATE SKU QUANTITY [NOTE]")
        raw_date, raw_sku, raw_qty, note = match.groups()
        date = parse_date(raw_date)
        if date is None:
            raise ParseError(number, "invalid date %r" % raw_date)
        sku = normalise_sku(raw_sku)
        if sku is None or sku not in catalog:
            raise ParseError(number, "unknown SKU %r" % raw_sku)
        quantity = None
        if _SIGNED_RE.fullmatch(raw_qty):
            try:
                quantity = int(raw_qty)
            except ValueError:  # absurdly long
                quantity = None
        if quantity is None:
            raise ParseError(number, "invalid quantity %r" % raw_qty)
